"""Tests for rules-in-context zero-shot LLM baseline."""from __future__ import annotationsimport pytestfrom zo_eval.predict_llm import RulesContextLLMPredictor, ServedLLMPredictorfrom zo_eval.rules_context import (    build_messages,    build_rules_digest,    build_step_vocab_digest,    load_generation_rules,    use_rules_in_context,)from zo_eval.submission import AnomalyInput, ValidInputfrom zo_train.datagen import ALL_RULES as DATAGEN_RULESfrom zo_train.fab import all_stepsMAX_DIGEST_CHARS = 16000def test_shared_base_in_zeroshot_system():    from zo_train.prompts import load_system_general    vi = ValidInput("e1", "MOSFET", 0.6, ["RECEIVE WAFER LOT"])    sys = build_messages("nextstep", vi)[0]["content"]    assert load_system_general().splitlines()[0] in sys    assert "TASK — Next-step prediction" in sys    assert "OUTPUT FORMAT" in sys    assert '"steps"' in sysdef test_default_prompt_has_no_rules_digest():    vi = ValidInput("e1", "MOSFET", 0.6, ["RECEIVE WAFER LOT"])    sys = build_messages("nextstep", vi)[0]["content"]    assert "Allowed fab step names for MOSFET" not in sys    assert "Forbidden patterns" not in sys    assert "Process grammar reference" not in sysdef test_step_vocab_in_prompt_when_rules_in_context(monkeypatch: pytest.MonkeyPatch):    monkeypatch.setenv("ZO_RULES_IN_CONTEXT", "1")    assert use_rules_in_context() is True    vi = ValidInput("e1", "MOSFET", 0.6, ["RECEIVE WAFER LOT"])    sys = build_messages("nextstep", vi)[0]["content"]    assert "Allowed fab step names for MOSFET" in sys    assert "MEASURE VIA CD" in sys    assert len(build_step_vocab_digest("MOSFET")) > 500    assert len(all_steps("MOSFET")) >= 100def test_anomaly_has_guidance_without_vocab_list():    an = build_messages("anomaly", AnomalyInput("a1", "MOSFET", ["RECEIVE WAFER LOT", "SHIP LOT"]))    sys = an[0]["content"]    assert "violation pattern" in sys.lower() or "violation patterns" in sys.lower()    assert "Reason first" in sys or "reasoning" in sys    assert "Default: valid=true" not in sys    assert "Most sequences are VALID" not in sys    assert "Allowed fab step names" not in sys    assert "Forbidden patterns" not in sysdef test_anomaly_digest_when_rules_in_context(monkeypatch: pytest.MonkeyPatch):    monkeypatch.setenv("ZO_RULES_IN_CONTEXT", "1")    an = build_messages("anomaly", AnomalyInput("a1", "MOSFET", ["RECEIVE WAFER LOT", "SHIP LOT"]))    sys = an[0]["content"]    assert "every forbidden rule" in sys    assert "Forbidden patterns" in sysdef test_nextstep_warns_against_block_labels():    vi = ValidInput("e1", "MOSFET", 0.6, ["A"])    sys = build_messages("nextstep", vi)[0]["content"]    assert "_BLOCK" in sys    assert "later process phase" in sys    assert "RULE_*" in sys and "anomaly" in sys.lower()def test_load_generation_rules_nonempty():    text = load_generation_rules()    assert "Process Sequence Generation Rules" in text    assert "RULE_DEP_NO_CLEAN" in textdef test_digest_contains_all_rules_and_backbone():    digest = build_rules_digest("MOSFET")    for rule in DATAGEN_RULES:        assert rule in digest    assert len(digest) < MAX_DIGEST_CHARSdef test_nextstep_user_message_numbered():    vi = ValidInput("e1", "MOSFET", 0.6, ["RECEIVE WAFER LOT", "LOT IDENTIFICATION"])    user = build_messages("nextstep", vi)[1]["content"]    assert "1. RECEIVE WAFER LOT" in user    assert "2. LOT IDENTIFICATION" in user    assert 'Last executed step (#2): "LOT IDENTIFICATION"' in user    assert " | " not in user.split("Respond")[0]def test_anomaly_user_message_numbered():    an = AnomalyInput("a1", "MOSFET", ["RECEIVE WAFER LOT", "SHIP LOT"])    user = build_messages("anomaly", an)[1]["content"]    assert "1. RECEIVE WAFER LOT" in user    assert "2. SHIP LOT" in userdef test_finetuned_nextstep_parses_json():    def fake_chat(messages, **kw):        return {            "choices": [                {                    "message": {                        "content": (                            '{"reasoning": "next", "steps": ["DEPOSIT BARRIER METAL", "CLEAN AFTER VIA ETCH"]}'                        )                    }                }            ]        }    p = ServedLLMPredictor(chat_fn=fake_chat)    vi = ValidInput("v1", "MOSFET", 0.6, ["RECEIVE WAFER LOT"])    assert p.next_step(vi)[0] == "DEPOSIT BARRIER METAL"def test_zeroshot_predictor_smoke():    def fake_chat(messages, **kw):        user = messages[-1]["content"]        if "Last executed step" in user:            c = '{"reasoning": "after lot id comes substrate prep", "steps": ["SPIN COAT PHOTORESIST", "SOFT BAKE"]}'        elif "Partial sequence (prefix" in user:            c = '{"reasoning": "finish route", "steps": ["DEPOSIT METAL 1", "SHIP LOT"]}'        else:            c = '{"reasoning": "valid sequence", "valid": true, "rule": null}'        return {"choices": [{"message": {"content": c}}]}    p = RulesContextLLMPredictor(chat_fn=fake_chat)    vi = ValidInput("v1", "MOSFET", 0.6, ["RECEIVE WAFER LOT"])    assert p.next_step(vi)[0] == "SPIN COAT PHOTORESIST"    iv, _, rule = p.anomaly(AnomalyInput("a1", "MOSFET", ["RECEIVE WAFER LOT", "SHIP LOT"]))    assert iv == 1 and rule is None